import{_ as a,o as n,c as e,a2 as i}from"./chunks/framework.RycU2wFZ.js";const k=JSON.parse('{"title":"Meta Prompt: Meilisearch Index Audit & Program Correctness Check","description":"","frontmatter":{},"headers":[],"relativePath":"meta-prompt-index-audit.md","filePath":"meta-prompt-index-audit.md","lastUpdated":1792785127000}'),p={name:"meta-prompt-index-audit.md"};function l(t,s,o,h,r,c){return n(),e("div",null,[...s[0]||(s[0]=[i('<h1 id="meta-prompt-meilisearch-index-audit-program-correctness-check" tabindex="-1">Meta Prompt: Meilisearch Index Audit &amp; Program Correctness Check <a class="header-anchor" href="#meta-prompt-meilisearch-index-audit-program-correctness-check" aria-label="Permalink to &quot;Meta Prompt: Meilisearch Index Audit &amp; Program Correctness Check&quot;">​</a></h1><p>Copy everything in the fenced block below into a new chat session. It gives the assistant enough context about this pipeline to (1) list the indices on the local Meilisearch instance and (2) verify the program is behaving correctly.</p><hr><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>You are auditing a Go data pipeline called &quot;auto-complete&quot; that builds two</span></span>\n<span class="line"><span>Meilisearch datasets for a travel autosuggest API.</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>## Workspace</span></span>\n<span class="line"><span>- Repo root: /Users/a670090449/Documents/travayo-v2/auto-complete</span></span>\n<span class="line"><span>- Language: Go 1.25 (uses modernc.org/sqlite, meilisearch-go)</span></span>\n<span class="line"><span>- Search engine: Meilisearch running locally</span></span>\n<span class="line"><span>- Config is loaded from `.env` at repo root.</span></span>\n<span class="line"><span>  - MEILI_HOST (default http://127.0.0.1:7700)</span></span>\n<span class="line"><span>  - MEILI_API_KEY (read from .env; do NOT print the key value back to me)</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>## What the pipeline produces</span></span>\n<span class="line"><span>Two live indices:</span></span>\n<span class="line"><span>- `places`  : cities, regions, neighborhoods, airports, train stations,</span></span>\n<span class="line"><span>              attractions, stadiums (OSM + OurAirports sources)</span></span>\n<span class="line"><span>- `hotels`  : hotel properties (Agoda feed)</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>## How indexing works (important for correctness reasoning)</span></span>\n<span class="line"><span>- The indexer uses BLUE/GREEN indexing.</span></span>\n<span class="line"><span>- For each run it builds a shadow index named `&lt;base&gt;__build_&lt;UTCtimestamp&gt;`,</span></span>\n<span class="line"><span>  e.g. `places__build_20260616231238`.</span></span>\n<span class="line"><span>- It uploads docs to the shadow, waits for Meilisearch task completion,</span></span>\n<span class="line"><span>  runs golden-query validation, then atomically swaps the shadow into the</span></span>\n<span class="line"><span>  live base name via the `/swap-indexes` endpoint.</span></span>\n<span class="line"><span>- Hotels indexing runs with `--allow-empty=true`: if 0 docs are produced it</span></span>\n<span class="line"><span>  SKIPS validation and swap (so a live `hotels` index may legitimately not</span></span>\n<span class="line"><span>  exist yet if the hotels feed has produced 0 rows).</span></span>\n<span class="line"><span>- Orchestrator entrypoint: `go run ./cmd/pipeline --stage run --target all`</span></span>\n<span class="line"><span>  (or `make run`). Stages: fetch | build-data | index | run | cleanup.</span></span>\n<span class="line"><span>- Cleanup entrypoint: `make cleanup` -&gt; `cmd/cleanup`.</span></span>\n<span class="line"><span>  - Groups indices by `&lt;base&gt;__build_` prefix.</span></span>\n<span class="line"><span>  - Keeps the newest N shadow builds per base (`--keep-builds`, default 3).</span></span>\n<span class="line"><span>  - Deletes older shadow builds. It does NOT delete live base indices.</span></span>\n<span class="line"><span>  - Also prunes manifests in `data/manifests/` older than `--keep-manifest-days`.</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>## Known problem to investigate</span></span>\n<span class="line"><span>The pipeline has been run many times and has accumulated too many leftover</span></span>\n<span class="line"><span>`__build_&lt;timestamp&gt;` shadow indices that were never cleaned up. There may also</span></span>\n<span class="line"><span>be `hotels__build_*` shadows that were never swapped to a live `hotels` index</span></span>\n<span class="line"><span>because the hotels feed produced 0 documents.</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>## Your tasks</span></span>\n<span class="line"><span>1. Fetch the list of index names on the local Meilisearch.</span></span>\n<span class="line"><span>   - Read MEILI_HOST and MEILI_API_KEY from `.env`.</span></span>\n<span class="line"><span>   - Call `GET {MEILI_HOST}/indexes?limit=1000` with</span></span>\n<span class="line"><span>     `Authorization: Bearer {MEILI_API_KEY}` if the key is set.</span></span>\n<span class="line"><span>   - Print, for each index: uid, primaryKey, and numberOfDocuments</span></span>\n<span class="line"><span>     (numberOfDocuments comes from `GET {host}/indexes/{uid}/stats`).</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>2. Classify each index as:</span></span>\n<span class="line"><span>   - LIVE base (`places`, `hotels`)</span></span>\n<span class="line"><span>   - SHADOW build (`&lt;base&gt;__build_&lt;timestamp&gt;`)</span></span>\n<span class="line"><span>   - UNKNOWN/orphan (anything else)</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>3. Check program correctness against these expectations:</span></span>\n<span class="line"><span>   - A live `places` index exists and has a non-trivial document count</span></span>\n<span class="line"><span>     (expected on the order of ~19k docs for the configured countries; treat</span></span>\n<span class="line"><span>     0 docs as a failure).</span></span>\n<span class="line"><span>   - `places` primaryKey is `id`.</span></span>\n<span class="line"><span>   - Document IDs are valid Meilisearch IDs (alphanumeric, `-`, `_`, &lt;=511</span></span>\n<span class="line"><span>     bytes). Sample a few docs via</span></span>\n<span class="line"><span>     `POST {host}/indexes/places/search` with body {&quot;q&quot;:&quot;&quot;,&quot;limit&quot;:5} and</span></span>\n<span class="line"><span>     confirm each `id` looks valid (no `&lt;nil&gt;`, no spaces/slashes).</span></span>\n<span class="line"><span>   - Run the golden queries in `config/golden_queries_places.txt`</span></span>\n<span class="line"><span>     (format: `query|expected_token_1,expected_token_2`, `#` = comment) against</span></span>\n<span class="line"><span>     the live `places` index and confirm each query returns hits containing the</span></span>\n<span class="line"><span>     expected tokens.</span></span>\n<span class="line"><span>   - Count shadow `__build_` indices per base. If more than 3 per base exist,</span></span>\n<span class="line"><span>     report it as cleanup debt.</span></span>\n<span class="line"><span>   - Note whether a live `hotels` index exists. If only `hotels__build_*`</span></span>\n<span class="line"><span>     shadows exist and no live `hotels`, explain that this is expected when the</span></span>\n<span class="line"><span>     hotels feed yields 0 docs (allow-empty mode) — not necessarily a bug.</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>4. Produce a concise report:</span></span>\n<span class="line"><span>   - Table of all indices (uid | type | docs | primaryKey)</span></span>\n<span class="line"><span>   - PASS/FAIL for each correctness expectation above</span></span>\n<span class="line"><span>   - Cleanup recommendation. To prune shadows safely, the intended command is:</span></span>\n<span class="line"><span>       make cleanup            # keeps newest 3 builds per base</span></span>\n<span class="line"><span>     or to keep only the latest build:</span></span>\n<span class="line"><span>       go run ./cmd/cleanup --keep-builds 1</span></span>\n<span class="line"><span>   - Do NOT delete the live `places` (or live `hotels`) index.</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>## Guardrails</span></span>\n<span class="line"><span>- Treat the local Meilisearch as the source of truth; the `.env` host/key are</span></span>\n<span class="line"><span>  the connection details.</span></span>\n<span class="line"><span>- Never print the API key value.</span></span>\n<span class="line"><span>- Do not delete any index unless I explicitly ask. First show me the report and</span></span>\n<span class="line"><span>  the proposed cleanup command.</span></span></code></pre></div><hr><h2 id="quick-reference-for-the-human-not-the-prompt" tabindex="-1">Quick reference (for the human, not the prompt) <a class="header-anchor" href="#quick-reference-for-the-human-not-the-prompt" aria-label="Permalink to &quot;Quick reference (for the human, not the prompt)&quot;">​</a></h2><ul><li>List indices manually:<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -E</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;^MEILI_API_KEY=&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> cut</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f2-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">HOST</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -E</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;^MEILI_HOST=&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> cut</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f2-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer ${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">KEY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">HOST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}/indexes?limit=1000&quot;</span></span></code></pre></div></li><li>Prune leftover shadow indices (keeps newest 3 per base by default):<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cleanup</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># or keep only the newest build per base:</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./cmd/cleanup</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --keep-builds</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span></span></code></pre></div></li><li>Cleanup never removes live base indices (<code>places</code>, <code>hotels</code>); it only trims <code>&lt;base&gt;__build_&lt;timestamp&gt;</code> shadows.</li></ul>',7)])])}const u=a(p,[["render",l]]);export{k as __pageData,u as default};
